function BenefitCard({
  title,
  description,
  subTitle,
  icon,
}: {
  title: string;
  description: string;
  subTitle: string;
  icon: React.ReactNode;
}) {
  return (
    <div className="bg-[#292929] flex flex-col md:flex-row gap-4 items-center rounded-[20px] flex-1 min-w-0 p-[20px]">
      <div className="w-10 h-10 flex items-center justify-center">{icon}</div>
      <div className="flex flex-col gap-[10px] text-white">
        <h3 className="text-[12px] font-medium  uppercase leading-[1.2]">
          {title}
        </h3>
        <p className="text-[16px] font-bold leading-[1.2]">{description}</p>
        <p className="text-[12px] font-medium leading-[1.2]">{subTitle}</p>
      </div>
    </div>
  );
}

