// ZKP Password Generator Section
const ZKPSection: React.FC<{
  domainName: string;
  memberData: any;
  verifyData?: any[];
  handleVerify?: (it: any) => void;
  theme?: ITheme;
}> = ({ domainName, memberData, verifyData, handleVerify, theme }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [isZkpChecked, setIsZkpChecked] = useState(false);
  const [storedZkpValid, setStoredZkpValid] = useState(false);
  const web3ClubService = useWeb3ClubService();
  const { address } = useAccount();

  const ZKP_STORAGE_KEY = `zkp_code_${address}`;
  const DEFAULT_COUNT = 10;

  // 页面加载时验证 localStorage 中的 ZKP 是否有效
  useEffect(() => {
    const validateStoredZkp = async () => {
      if (!address) {
        setIsZkpChecked(true);
        return;
      }

      const storedCode = localStorage.getItem(ZKP_STORAGE_KEY);
      if (!storedCode) {
        setStoredZkpValid(false);
        setIsZkpChecked(true);
        return;
      }

      const valid = await isZkpValid(storedCode);
      setStoredZkpValid(valid);
      setIsZkpChecked(true);

      if (!valid) {
        // 清除无效的 ZKP code
        localStorage.removeItem(ZKP_STORAGE_KEY);
      }
    };

    validateStoredZkp();
  }, [address, ZKP_STORAGE_KEY]);

  const getStoredZkpCode = (): string | null => {
    if (!address) return null;
    // 只有验证通过才返回存储的 code
    if (!storedZkpValid) return null;
    return localStorage.getItem(ZKP_STORAGE_KEY);
  };

  const generateZkpCode = async (): Promise<string | null> => {
    try {
      setIsGenerating(true);
      const res = await web3ClubService.proofOfOwnershipClient.submitProof(
        BigInt(DEFAULT_COUNT),
      );
      if (res && address) {
        localStorage.setItem(ZKP_STORAGE_KEY, res);
      }
      return res;
    } catch (error) {
      console.error("Failed to generate ZKP code:", error);
      return null;
    } finally {
      setIsGenerating(false);
    }
  };

  const handleServiceClick = async (e: React.MouseEvent, href: string) => {
    e.preventDefault();

    if (!address) {
      toast.error("Please connect your wallet first.");
      return;
    }

    const isMember =
      memberData?.isPermanent ||
      memberData?.isTemporary ||
      memberData?.isTokenBased ||
      memberData?.isCrossChain;

    if (!isMember) {
      toast.error("Please purchase membership to join the club first.");
      return;
    }

    let zkpCode = getStoredZkpCode();

    // 如果需要生成，先打开窗口（避免浏览器阻止异步后的弹窗）
    let newWindow: Window | null = null;
    if (!zkpCode) {
      newWindow = window.open("about:blank", "_blank");
      toast.info("Generating ZKP code...");
      zkpCode = await generateZkpCode();
      if (!zkpCode) {
        newWindow?.close();
        toast.error("Failed to generate ZKP code. Please try again.");
        return;
      }
      // 生成成功后更新状态
      setStoredZkpValid(true);
      toast.success("ZKP code generated successfully!");
    }

    // Base64 编码 ZKP code，避免 URL 解析问题
    const encodedZkp = btoa(zkpCode);
    const url = new URL(href);
    url.searchParams.set("zkp", encodedZkp);

    if (newWindow) {
      newWindow.location.href = url.toString();
    } else {
      window.open(url.toString(), "_blank");
    }
  };

  const serviceCards = [
    {
      icon: <JustHubIcon />,
      title: "JustHub",
      description:
        "Member-only posts and gated content with simple access rules.",
      linkText: "登录",
      linkHref: "https://justhub.net/login",
    },
    {
      icon: <InnerAIIcon />,
      title: "InnerAI",
      description: "AI 社区内部免费 API，每位成员每月 1,500 美元额度。",
      linkText: "登录",
      linkHref: "https://innerai.net/login",
    },
  ];

  return (
    <section className="flex flex-col gap-[40px] items-center py-[40px]">
      <ZKPPassword
        domainName={domainName}
        memberData={memberData}
        className="w-full max-w-[960px]"
        headerClassName="gap-[20px]"
        titleClassName="text-white text-[32px] uppercase"
        titleRender={
          <span>
            ZKP Temporary
            <br />
            Password Generator
          </span>
        }
        descriptionClassName="text-white/60"
        linkClassName="text-[#da7758] no-underline"
        lineClassName="hidden"
        controlsClassName="bg-black rounded-[20px] p-5"
        labelClassName="text-white text-base uppercase"
        counterClassName="bg-[#292929] border-2 border-white/20 rounded-[10px] p-[10px] text-white"
        buttonClassName="bg-[#da7758] text-white rounded-[5px]"
        generateBtnClassName="bg-[#da7758] text-white rounded-[30px] h-auto px-10 py-[10px] flex items-center gap-[10px]"
        generateLabel={
          <div className="flex items-center justify-center gap-[10px]">
            <span className="bg-white p-[10px] rounded-full text-black">
              <ArrowRightAlt />
            </span>
            Generate{" "}
          </div>
        }
        resultBtnClassName="bg-[#da7758] text-white"
        resultIconFill="#da7758"
        loadingIconClassName="text-white"
        loadingTextClassName="text-white/80"
      />

      {/* Service Cards */}
      <div className="flex gap-[30px] w-full">
        {serviceCards.map((card, index) => (
          <ServiceCard
            key={index}
            {...card}
            onLinkClick={(e) => handleServiceClick(e, card.linkHref)}
            isLoading={isGenerating}
          />
        ))}
      </div>

      {/* Position Verification Section */}
      {verifyData?.length > 0 && (
        <div className="flex flex-col gap-[40px] items-center w-full pt-[40px]">
          <h2 className="text-white text-[32px] font-bold uppercase tracking-wider">
            Position Verification
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-[20px] w-full">
            {verifyData.map((it: any, index: number) => (
              <div
                key={index}
                className="bg-black rounded-[10px] p-6 flex flex-col gap-4 border-l-4 border-[#da7758]"
              >
                <img
                  src={theme?.verifyImgs?.[index] || theme?.verifyImgs?.[0] || "/aave.png"}
                  alt={`${it.chainName} Chain`}
                  className="w-[80px] h-[30px] object-contain"
                />
                <div className="flex flex-col gap-2">
                  <span className="text-white text-base font-bold">
                    {it.chainName} Chain
                  </span>
                  <span className="text-white/80 text-sm">
                    Hold {it.tokenSymbol}≥{formatUnits(it.threshold, it.decimals)}
                  </span>
                </div>
                <button
                  onClick={() => handleVerify?.(it)}
                  className="text-[#da7758] text-sm font-bold uppercase flex items-center gap-2 w-fit"
                >
                  VERIFY
                  <span>→</span>
                </button>
              </div>
            ))}
          </div>
        </div>
      )}
    </section>
  );
};

