import { useState, useEffect, useCallback } from "react";
import { useAccount } from "wagmi";
import { Social } from "@/types";
import {
  isZkpValid,
  getStoredZkpCode,
  getZkpStorageKey,
} from "../utils/zkpValidator";

export interface UseZkpSocialLinksReturn {
  isZkpValid: boolean;
  isZkpChecking: boolean;
  handleSocialClick: (social: Social) => void;
}

export function useZkpSocialLinks(): UseZkpSocialLinksReturn {
  const { address } = useAccount();
  const [zkpValid, setZkpValid] = useState(false);
  const [isZkpChecking, setIsZkpChecking] = useState(true);

  // 页面加载时验证 localStorage 中的 ZKP 是否有效
  useEffect(() => {
    const validateStoredZkp = async () => {
      if (!address) {
        setIsZkpChecking(false);
        setZkpValid(false);
        return;
      }

      const storedCode = getStoredZkpCode(address);
      if (!storedCode) {
        setZkpValid(false);
        setIsZkpChecking(false);
        return;
      }

      const valid = await isZkpValid(storedCode);
      setZkpValid(valid);
      setIsZkpChecking(false);

      if (!valid) {
        localStorage.removeItem(getZkpStorageKey(address));
      }
    };

    validateStoredZkp();
  }, [address]);

  const handleSocialClick = useCallback(
    (social: Social) => {
      let targetUrl = social.link;

      // 如果启用了 zkp 且有有效的 zkp code
      if (social.zkpEnabled && address && zkpValid) {
        const zkpCode = getStoredZkpCode(address);
        if (zkpCode) {
          try {
            const encodedZkp = btoa(zkpCode);
            const url = new URL(targetUrl);
            url.searchParams.set("zkp", encodedZkp);
            targetUrl = url.toString();
          } catch {
            // URL 解析失败，使用原始链接
          }
        }
      }

      window.open(targetUrl, "_blank");
    },
    [address, zkpValid]
  );

  return {
    isZkpValid: zkpValid,
    isZkpChecking,
    handleSocialClick,
  };
}
