import { globalConfig } from "@/constants";
import {
  ContractClientBase,
  ContractClientBaseOptions,
} from "./ContractClient";
import { ProofOfOwnershipABI } from "./abis/ProofOfOwnership";
import { Address } from "viem";
import { Groth16VerifierClient } from "./Groth16VerfifierClient";
import zkGenerator from "./ZkProofGenerator";

export class ProofOfOwnershipClient extends ContractClientBase<
  typeof ProofOfOwnershipABI
> {
  options: Partial<ContractClientBaseOptions>;
  constructor(options: Partial<ContractClientBaseOptions>) {
    super({
      ...options,
      chain: globalConfig.chain,
      contractAddress: globalConfig.proofOfOwnershipAddress as Address,
      abi: ProofOfOwnershipABI,
    });
    this.options = options;
  }

  get verifierClient() {
    return new Groth16VerifierClient(this.options);
  }

  /**
   * 1. 格式化证明数据用于 Verifier 验证
   * @param {Object} proof - snarkjs 生成的 proof 对象
   * @param {Array} publicSignals - snarkjs 生成的 publicSignals
   */
  formatForVerifier(proof: any, publicSignals: any[]) {
    const toHex = (val: any) => "0x" + BigInt(val).toString(16);
    return {
      pi_a: [toHex(proof.pi_a[0]), toHex(proof.pi_a[1])] as const,
      pi_b: [
        [toHex(proof.pi_b[0][1]), toHex(proof.pi_b[0][0])],
        [toHex(proof.pi_b[1][1]), toHex(proof.pi_b[1][0])],
      ] as const,
      pi_c: [toHex(proof.pi_c[0]), toHex(proof.pi_c[1])] as const,
      input: publicSignals.map(toHex),
    };
  }

  formatCompleteProof(generatedProof: any) {
    if (!generatedProof || !generatedProof.proof) {
      return "";
    }

    try {
      // 将proof对象转换为连续的十六进制字符串
      const proof = generatedProof.proof;

      // 将所有部分连接成一个连续的十六进制字符串
      const parts = [];

      // pi_a - 2 个元素
      parts.push(BigInt(proof.pi_a[0]).toString(16).padStart(64, "0"));
      parts.push(BigInt(proof.pi_a[1]).toString(16).padStart(64, "0"));

      // pi_b - 2x2 = 4 个元素 (需要反转顺序)
      parts.push(BigInt(proof.pi_b[0][1]).toString(16).padStart(64, "0"));
      parts.push(BigInt(proof.pi_b[0][0]).toString(16).padStart(64, "0"));
      parts.push(BigInt(proof.pi_b[1][1]).toString(16).padStart(64, "0"));
      parts.push(BigInt(proof.pi_b[1][0]).toString(16).padStart(64, "0"));

      // pi_c - 2 个元素
      parts.push(BigInt(proof.pi_c[0]).toString(16).padStart(64, "0"));
      parts.push(BigInt(proof.pi_c[1]).toString(16).padStart(64, "0"));

      // 第九段：添加 hasher (public input)
      const hasher = generatedProof.publicSignals[0];
      parts.push(BigInt(hasher).toString(16).padStart(64, "0"));

      // 组合成完整的proof字符串，每个都加 0x 前缀，用逗号分隔
      const completeProof = parts.map((p) => "0x" + p).join(",");

      return completeProof;
    } catch (error) {
      console.error("Format complete proof failed:", error);
      return "Error formatting proof";
    }
  }

  async submitProof(usageCount: bigint) {
    const nullifier = zkGenerator.generateRandomNullifier();
    const hasher = zkGenerator.calculatePoseidonHash(nullifier);
    const proofResult = await zkGenerator.generateProof(nullifier, hasher);
    const { proof, publicSignals } = proofResult;
    const formatted = this.formatForVerifier(proof, publicSignals);

    console.log("Step 1: Verifying proof off-chain (View Call)...");
    try {
      // 调用验证合约的 view 函数进行预检查
      const isValid = await this.verifierClient.verifyProof(
        formatted.pi_a as any,
        formatted.pi_b as any,
        formatted.pi_c as any,
        formatted.input as any
      );

      if (!isValid) {
        throw new Error("ZK Proof verification failed on Verifier contract.");
      }
      console.log("✅ Proof is valid.");
    } catch (error: any) {
      console.warn("Verification check failed or skipped:", error.message);
      // 可以在这里决定是否终止流程
    }

    console.log("Step 2: Preparing transaction...");

    // 获取 Public Input (即 Nullifier 的 Poseidon Hash)
    // 这里的逻辑对应 login.vue 中的 proofHash = this.publicInput
    let publicInputHash = formatted.input[0];

    // 确保格式为 bytes32 (64 hex chars + 0x)
    if (publicInputHash.length < 66) {
      publicInputHash =
        "0x" + publicInputHash.replace("0x", "").padStart(64, "0");
    }
    console.log("Step 3: Sending transaction to storeProof...");

    // 发送交易
    // 注意：storeProof 只接收 Hash 和 UsageCount
    const tx = await this.simulateAndWriteContract({
      functionName: "storeProof",
      args: [publicInputHash as `0x${string}`, usageCount],
      value: (await this.readContract({
        functionName: "calculateTotalFee",
        args: [usageCount],
      })) as unknown as bigint,
    });
    await this.waitForTransactionReceipt({
      hash: tx,
    });

    console.log("Transaction successful:", tx);
    return this.formatCompleteProof(proofResult);
  }
}
