import { Button } from "../../components/ui/button";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "../../components/ui/dialog";
import { ArrowRight } from "lucide-react";

interface MemberData {
  isPermanent: boolean;
  isTemporary: boolean;
  isTokenBased: boolean;
  isCrossChain: boolean;
}

export const MemberModal = ({
  open,
  setOpen,
  data = {
    isPermanent: false,
    isTemporary: true,
    isTokenBased: false,
    isCrossChain: false,
  },
  isVerifyMode = false,
  onConfirm,
}: {
  open: boolean;
  setOpen: (open: boolean) => void;
  data?: MemberData;
  isVerifyMode?: boolean;
  onConfirm: () => void;
}) => {
  const getMemberTypes = () => {
    const types = [];
    if (data?.isTemporary) types.push("Temporary Member");
    if (data?.isPermanent) types.push("Permanent Member");
    if (data?.isTokenBased) types.push("Token Holder");
    if (data?.isCrossChain) types.push("Cross Chain Member");
    return types;
  };

  const memberTypes = getMemberTypes();

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="w-[90vw] md:w-[480px] bg-[#292929] border-2 border-black rounded-[20px] p-0">
        <div className="flex flex-col p-8 gap-6">
          <DialogHeader className="p-0">
            <DialogTitle className="text-white text-2xl font-bold text-center">
              提示
            </DialogTitle>
          </DialogHeader>

          <div className="flex flex-col gap-4">
            <p className="text-white/80 text-sm">您已拥有以下访问权限：</p>

            <div className="text-[#da7758] text-base font-bold">
              {memberTypes.map((type, index) => (
                <div key={index}>{type}</div>
              ))}
            </div>

            <p className="text-white/60 text-sm">
              {isVerifyMode ? "是否仍要再次验证？" : "是否仍要再次加入此社区？"}
            </p>

            <div className="flex gap-4 mt-2">
              <DialogClose asChild>
                <Button className="flex-1 bg-white/20 hover:bg-white/30 text-white text-sm font-bold rounded-[30px] h-12">
                  取消
                </Button>
              </DialogClose>

              <Button
                onClick={onConfirm}
                className="flex-1 bg-[#da7758] hover:bg-[#da7758]/90 text-white text-sm font-bold rounded-[30px] h-12 flex items-center justify-center gap-2"
              >
                确认
                <ArrowRight className="w-5 h-5" />
              </Button>
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};
