import * as snarkjs from "snarkjs";
// 使用 poseidon-lite 进行哈希计算 (浏览器环境兼容性更好)
import { poseidon1 } from "poseidon-lite";

export interface Groth16Proof {
  pi_a: string[];
  pi_b: string[][];
  pi_c: string[];
  protocol: string;
  curve: string;
}

export type PublicSignals = string[];

// 配置常量
const ZK_CONFIG = {
  // 电路文件路径 (根据你的项目结构调整)
  wasmUrl: "/circuits/police_verify.wasm",
  zkeyUrl: "/circuits/police_verify_final.zkey",
  // 椭圆曲线域大小 (BN128)
  FIELD_SIZE:
    "21888242871839275222246405745257275088548364400416034343698204186575808495617",
};

export type ZkConfig = typeof ZK_CONFIG;

export interface CircuitInput {
  nullifier: string;
  hasher: string;
  [key: string]: string;
}

export interface FormattedProof {
  pi_a: [string, string];
  pi_b: [[string, string], [string, string]];
  pi_c: [string, string];
  input: string[];
}

export interface ProofResult {
  proof: Groth16Proof;
  publicSignals: PublicSignals;
  solidityParams: FormattedProof;
}

class ZkProofGenerator {
  private config: ZkConfig;
  private wasmBuffer: ArrayBuffer | null;
  private zkeyBuffer: ArrayBuffer | null;
  private circuitLoaded: boolean;

  constructor(config: ZkConfig = ZK_CONFIG) {
    this.config = config;
    this.wasmBuffer = null;
    this.zkeyBuffer = null;
    this.circuitLoaded = false;
  }

  /**
   * 1. 生成随机 Nullifier (隐私输入)
   * 生成一个在有效域范围内的随机大整数
   */
  generateRandomNullifier(): string {
    const fieldSize = BigInt(this.config.FIELD_SIZE);
    const maxAttempts = 10;
    let attempts = 0;

    while (attempts < maxAttempts) {
      // 生成 31 字节的随机数 (确保小于 32 字节的 field size)
      const randomBytes = new Uint8Array(31);
      if (typeof crypto !== "undefined") {
        crypto.getRandomValues(randomBytes);
      } else {
        // Node.js 环境适配 (Dynamic import to avoid build issues in browser-only environments if not polyfilled)
        // Note: In a strict browser environment without node polyfills, this branch might fail if 'crypto' is not available globally.
        // However, modern browsers support global `crypto`.
        try {
          // eslint-disable-next-line @typescript-eslint/no-var-requires
          const nodeCrypto = require("crypto");
          const buf = nodeCrypto.randomBytes(31);
          for (let i = 0; i < 31; i++) randomBytes[i] = buf[i];
        } catch (e) {
          console.error("Crypto module not found", e);
          throw new Error(
            "Secure random number generation not supported in this environment"
          );
        }
      }

      let nullifierHex = "";
      for (let i = 0; i < randomBytes.length; i++) {
        nullifierHex += randomBytes[i].toString(16).padStart(2, "0");
      }

      const result = BigInt("0x" + nullifierHex);

      // 确保在有效范围内
      if (result > 0n && result < fieldSize) {
        return result.toString();
      }
      attempts++;
    }
    throw new Error("Failed to generate valid nullifier");
  }

  /**
   * 2. 计算 Poseidon 哈希 (公开输入)
   * @param {string} nullifier - 大整数字符串
   */
  calculatePoseidonHash(nullifier: string): string {
    try {
      const input = BigInt(nullifier);
      const fieldSize = BigInt(this.config.FIELD_SIZE);

      if (input <= 0n || input >= fieldSize) {
        throw new Error(`Nullifier out of range`);
      }

      // poseidon-lite 的输入需要是字符串数组
      const hash = poseidon1([input.toString()]);
      return BigInt(hash.toString()).toString();
    } catch (error) {
      console.error("Hash calculation failed:", error);
      throw error;
    }
  }

  /**
   * 3. 加载电路文件 (WASM 和 ZKey)
   * 支持缓存，避免重复加载
   */
  async loadCircuitFiles(): Promise<void> {
    if (this.circuitLoaded && this.wasmBuffer && this.zkeyBuffer) {
      return;
    }

    try {
      console.log("Loading circuit files...");

      // 浏览器环境使用 fetch
      const [wasmResp, zkeyResp] = await Promise.all([
        fetch(this.config.wasmUrl),
        fetch(this.config.zkeyUrl),
      ]);

      if (!wasmResp.ok || !zkeyResp.ok) {
        throw new Error("Failed to fetch circuit files");
      }

      this.wasmBuffer = await wasmResp.arrayBuffer();
      this.zkeyBuffer = await zkeyResp.arrayBuffer();
      this.circuitLoaded = true;
      console.log("Circuit files loaded successfully");
    } catch (error: any) {
      throw new Error(`Load circuit files failed: ${error.message}`);
    }
  }

  /**
   * 4. 生成零知识证明 (核心方法)
   * @param {string} nullifier
   * @param {string} hasher
   */
  async generateProof(nullifier: string, hasher: string): Promise<ProofResult> {
    // 验证哈希匹配
    const calculatedHasher = this.calculatePoseidonHash(nullifier);
    if (calculatedHasher !== hasher) {
      throw new Error(
        "Hash mismatch: nullifier does not hash to provided hasher"
      );
    }

    // 确保电路已加载
    await this.loadCircuitFiles();

    if (!this.wasmBuffer || !this.zkeyBuffer) {
      throw new Error("Circuit files not loaded correctly");
    }

    // 准备电路输入
    const circuitInput: CircuitInput = {
      nullifier: nullifier,
      hasher: hasher,
    };

    console.log("Generating proof with input:", circuitInput);

    // 使用 snarkjs 生成证明
    const { proof, publicSignals } = await snarkjs.groth16.fullProve(
      circuitInput,
      new Uint8Array(this.wasmBuffer),
      new Uint8Array(this.zkeyBuffer)
    );

    // 格式化为 Solidity 可用参数
    const solidityParams = this.formatSolidityCallParams(proof, publicSignals);

    return {
      proof: proof as Groth16Proof,
      publicSignals: publicSignals as PublicSignals,
      solidityParams,
    };
  }

  /**
   * 5. 格式化参数用于 Solidity 合约调用
   */
  formatSolidityCallParams(proof: any, publicSignals: any[]): FormattedProof {
    const toHex = (val: any) => "0x" + BigInt(val).toString(16);

    return {
      pi_a: [toHex(proof.pi_a[0]), toHex(proof.pi_a[1])],
      pi_b: [
        [toHex(proof.pi_b[0][1]), toHex(proof.pi_b[0][0])],
        [toHex(proof.pi_b[1][1]), toHex(proof.pi_b[1][0])],
      ],
      pi_c: [toHex(proof.pi_c[0]), toHex(proof.pi_c[1])],
      input: publicSignals.map(toHex),
    };
  }
}

export default new ZkProofGenerator();
