import { formatEther } from "viem";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "./ui/dialog";
import { Button } from "./ui/button";
import { useStripeCheckout } from "../hooks/useStripeCheckout";
import { Loader2, Copy, Check } from "lucide-react";
import { STRIPE_TOPUP_ENABLED } from "../constants";
import { QRCodeSVG } from "qrcode.react";
import { useState } from "react";

interface InsufficientBalanceModalProps {
  open: boolean;
  onClose: () => void;
  balance: bigint;
  required: bigint;
  shortfall: bigint;
  domainName: string;
  membershipType: string;
  ethPrice?: number;
  walletAddress?: string;
}

export function InsufficientBalanceModal({
  open,
  onClose,
  balance,
  required,
  shortfall,
  domainName,
  membershipType,
  ethPrice = 0,
  walletAddress,
}: InsufficientBalanceModalProps) {
  const { createCheckoutSession, isLoading, error } = useStripeCheckout();
  const [copied, setCopied] = useState(false);

  const shortfallEth = formatEther(shortfall);
  const balanceEth = formatEther(balance);
  const requiredEth = formatEther(required);
  const shortfallUsd = (parseFloat(shortfallEth) * ethPrice).toFixed(2);

  const handleCopyAddress = async () => {
    if (walletAddress) {
      await navigator.clipboard.writeText(walletAddress);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const handleStripePayment = async () => {
    await createCheckoutSession({
      domainName,
      membershipType,
      ethAmount: shortfallEth,
    });
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Insufficient Balance</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div className="bg-gray-100 rounded-lg p-4 space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-gray-600">Current Balance</span>
              <span>{parseFloat(balanceEth).toFixed(6)} ETH</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-gray-600">Required Amount</span>
              <span>{parseFloat(requiredEth).toFixed(6)} ETH</span>
            </div>
            <div className="border-t pt-2 flex justify-between font-medium">
              <span className="text-red-600">Shortfall</span>
              <span className="text-red-600">
                {parseFloat(shortfallEth).toFixed(6)} ETH
                {ethPrice > 0 && ` (~$${shortfallUsd})`}
              </span>
            </div>
          </div>

          {walletAddress && (
            <div className="bg-gray-100 rounded-lg p-4 space-y-3">
              <div className="text-sm text-gray-600 text-center">Your Wallet Address</div>
              <div className="flex justify-center">
                <QRCodeSVG value={walletAddress} size={120} />
              </div>
              <div className="flex items-center gap-2 bg-white rounded px-3 py-2">
                <span className="text-xs font-mono flex-1 truncate">{walletAddress}</span>
                <button onClick={handleCopyAddress} className="text-gray-500 hover:text-gray-700">
                  {copied ? <Check className="h-4 w-4 text-green-500" /> : <Copy className="h-4 w-4" />}
                </button>
              </div>
            </div>
          )}

          {error && (
            <p className="text-red-500 text-sm">{error}</p>
          )}

          <div className="flex gap-3">
            <Button variant="outline" onClick={onClose} className="flex-1">
              Cancel
            </Button>
            {STRIPE_TOPUP_ENABLED && (
              <Button
                onClick={handleStripePayment}
                disabled={isLoading}
                className="flex-1"
              >
                {isLoading ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Processing...
                  </>
                ) : (
                  "Pay with Stripe"
                )}
              </Button>
            )}
          </div>

          {STRIPE_TOPUP_ENABLED ? (
            <p className="text-xs text-gray-500 text-center">
              After payment, ETH will be automatically transferred to your wallet
            </p>
          ) : (
            <p className="text-xs text-gray-500 text-center">
              Please top up ETH to your wallet via exchange or other methods
            </p>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}
