import { useState } from "react";
import { useAccount, useSignMessage } from "wagmi";
import { supabaseConfig } from "../constants";

const SUPABASE_FUNCTIONS_URL = `${supabaseConfig.apiUrl}/functions/v1`;

interface CheckoutParams {
  domainName: string;
  membershipType: string;
  ethAmount: string;
}

export function useStripeCheckout() {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { address } = useAccount();
  const { signMessageAsync } = useSignMessage();

  const createCheckoutSession = async (params: CheckoutParams) => {
    if (!address) {
      setError("Please connect your wallet first");
      return null;
    }

    setIsLoading(true);
    setError(null);

    try {
      const timestamp = Date.now();
      const message = `I confirm ETH topup to wallet ${address} at timestamp ${timestamp}`;

      // 1. 签名消息
      const signature = await signMessageAsync({ message, account: address });

      // 2. 创建支付会话
      const response = await fetch(
        `${SUPABASE_FUNCTIONS_URL}/create-checkout-session`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            walletAddress: address,
            signature,
            message,
            timestamp,
            ...params,
          }),
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Failed to create checkout session");
      }

      // 3. 跳转到 Stripe
      if (data.url) {
        window.location.href = data.url;
      }

      return data;
    } catch (err: any) {
      setError(err.message || "Failed to create checkout session");
      return null;
    } finally {
      setIsLoading(false);
    }
  };

  return { createCheckoutSession, isLoading, error };
}
