import { globalConfig } from "@/constants";
import {
  ContractClientBase,
  ContractClientBaseOptions,
} from "./ContractClient";
import { Address } from "viem";
import { Groth16VerifierABI } from "./abis/Groth16Verifier";

export class Groth16VerifierClient extends ContractClientBase<
  typeof Groth16VerifierABI
> {
  constructor(options: Partial<ContractClientBaseOptions>) {
    super({
      ...options,
      chain: globalConfig.chain,
      contractAddress: globalConfig.groth16VerifierAddress as Address,
      abi: Groth16VerifierABI,
    });
  }

  async verifyProof(
    _pA: readonly [bigint, bigint],
    _pB: readonly [readonly [bigint, bigint], readonly [bigint, bigint]],
    _pC: readonly [bigint, bigint],
    _pubSignals: readonly [bigint]
  ): Promise<boolean> {
    return this.readContract({
      functionName: "verifyProof",
      args: [_pA, _pB, _pC, _pubSignals],
    }) as unknown as boolean;
  }
}
