import React, { ReactNode, useState, useEffect } from "react";
import { cn } from "@/lib/utils";
import { LoaderCircle, CheckCircle } from "lucide-react";
import { useWeb3ClubService } from "./AppkitProvider";
import { toast } from "sonner";
import { useAccount } from "wagmi";
import { useQuery } from "@tanstack/react-query";
import { isZkpValid } from "../utils/zkpValidator";

export interface ZKPPasswordProps {
  /**
   * The domain name of the club.
   */
  domainName?: string;
  /**
   * The member data of the current user.
   */
  memberData?: any;
  /**
   * Optional class name for the wrapper.
   */
  className?: string;
  /**
   * Optional inline styles for the wrapper.
   */
  style?: React.CSSProperties;

  /* Customization props */
  headerClassName?: string;
  titleClassName?: string;
  descriptionClassName?: string;
  linkClassName?: string;
  controlsClassName?: string;
  labelClassName?: string;
  counterClassName?: string;
  buttonClassName?: string; // for -/+
  generateBtnClassName?: string;

  /* Content props */
  icon?: React.ReactNode;
  generateLabel?: ReactNode;
  resultBtnClassName?: string;
  resultIconFill?: string;
  loadingIconClassName?: string;
  loadingTextClassName?: string;
  lineClassName?: string;
  titleRender?: ReactNode;
}

export function ZKPPassword({
  className,
  style,
  headerClassName,
  titleClassName,
  descriptionClassName,
  linkClassName,
  controlsClassName,
  labelClassName,
  counterClassName,
  buttonClassName,
  generateBtnClassName,
  icon,
  generateLabel = "Generate",
  resultBtnClassName,
  resultIconFill = "#00B800",
  loadingIconClassName,
  loadingTextClassName,
  lineClassName,
  titleRender,
  domainName,
  memberData,
}: ZKPPasswordProps) {
  const [count, setCount] = useState(10);
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const [storedZkpValid, setStoredZkpValid] = useState(false);
  const web3ClubService = useWeb3ClubService();
  const { address } = useAccount();

  const ZKP_STORAGE_KEY = `zkp_code_${address}`;

  // 页面加载时验证 localStorage 中的 ZKP 是否有效
  useEffect(() => {
    const validateStoredZkp = async () => {
      if (!address) return;

      const storedCode = localStorage.getItem(ZKP_STORAGE_KEY);
      if (!storedCode) {
        setStoredZkpValid(false);
        return;
      }

      const valid = await isZkpValid(storedCode);
      setStoredZkpValid(valid);

      if (!valid) {
        localStorage.removeItem(ZKP_STORAGE_KEY);
      }
    };

    validateStoredZkp();
  }, [address, ZKP_STORAGE_KEY]);

  const { data: owner } = useQuery({
    queryKey: ["owner", domainName],
    queryFn: () =>
      domainName
        ? web3ClubService.web3ClubNFTClient.getOwner(domainName)
        : Promise.resolve(null),
    enabled: !!domainName,
  });

  const isOwner =
    address && owner && address.toLowerCase() === owner.toLowerCase();
  const isMember =
    memberData?.isPermanent ||
    memberData?.isTemporary ||
    memberData?.isTokenBased ||
    memberData?.isCrossChain;

  const handleIncrement = () => setCount((c) => c + 1);
  const handleDecrement = () => setCount((c) => Math.max(1, c - 1));

  const handleGenerate = async (count: number) => {
    if (domainName) {
      if (!isMember && !isOwner) {
        toast.error("Please purchase membership to join the club first.");
        return;
      }
    }

    setIsLoading(true);
    try {
      const res = await web3ClubService.proofOfOwnershipClient.submitProof(
        BigInt(count),
      );
      setResult(res);

      // 保存到 localStorage
      if (res && address) {
        localStorage.setItem(ZKP_STORAGE_KEY, res);
        setStoredZkpValid(true);
      }

      console.log("Generating password with count:", count);
      toast.success("Password generated successfully!");
    } catch (error: any) {
      setIsLoading(false);
      toast.error(
        error?.message || "Failed to generate password. Please try again.",
      );
      console.error("Failed to generate password:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = () => {
    if (result) {
      navigator.clipboard.writeText(result);
      toast.success("Password copied to clipboard!");
    }
  };

  const handleReset = () => {
    setResult(null);
  };

  const renderContent = () => {
    if (isLoading) {
      return (
        <div
          className={cn(
            "flex items-center gap-[20px] px-[40px] py-[30px] bg-[#f8f8f8] rounded-[4px] h-[131px]",
            controlsClassName,
          )}
        >
          <LoaderCircle
            className={cn(
              "animate-spin w-[40px] h-[40px] text-black",
              loadingIconClassName,
            )}
          />
          <div className="grow flex items-center justify-center p-[16px]">
            <span
              className={cn(
                "text-black/80 text-[14px] font-medium",
                loadingTextClassName,
              )}
            >
              Waiting for blockchain confirmation...
            </span>
          </div>
        </div>
      );
    }

    if (result) {
      return (
        <div
          className={cn(
            "flex flex-col md:flex-row items-center gap-[20px] px-5 md:px-[40px] py-2.5 md:py-[30px] bg-[#f8f8f8] rounded-[4px]",
            controlsClassName,
          )}
        >
          <div className="shrink-0">
            <svg
              width="35"
              height="36"
              viewBox="0 0 35 36"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                d="M17.4897 0C7.83041 0 0 8.02629 0 17.927C0 27.8279 7.83041 35.8541 17.4897 35.8541C27.1491 35.8541 34.9796 27.8279 34.9796 17.927C34.9796 8.02629 27.1491 0 17.4897 0ZM13.7255 26.7315L11.6767 24.6316L11.6631 24.6454L6.16662 19.0115L8.2279 16.8988L13.712 22.5199L26.7583 9.14746L28.8195 11.2603L13.7255 26.7315Z"
                fill={resultIconFill}
              />
            </svg>
          </div>
          <div className="grow border border-black bg-white p-[15px] rounded-[4px]">
            <p className="m-0 text-black/80 text-[14px] font-medium break-all">
              {result}
            </p>
          </div>
          <div className="flex items-center gap-[10px] shrink-0">
            <button
              type="button"
              onClick={handleCopy}
              className={cn(
                "flex px-[30px] py-[8px] justify-center items-center gap-[10px] self-stretch rounded-[20px] bg-[#E3E337] border-none text-black text-[14px] font-medium cursor-pointer hover:opacity-90 transition-opacity",
                resultBtnClassName,
              )}
            >
              Copy
            </button>
            <button
              type="button"
              onClick={handleReset}
              className={cn(
                "flex px-[30px] py-[8px] justify-center items-center gap-[10px] self-stretch rounded-[20px] bg-[#F8F8F8] border-none text-black text-[14px] font-medium cursor-pointer hover:opacity-90 transition-opacity",
                resultBtnClassName,
              )}
            >
              Reset
            </button>
          </div>
        </div>
      );
    }

    return (
      <div
        className={cn(
          "flex md:items-center flex-col md:flex-row gap-[20px] px-[40px] py-[30px] bg-[#F8F8F8] rounded-[20px]",
          controlsClassName,
        )}
      >
        <span
          className={cn(
            "font-bold text-[#333] text-center text-[16px]",
            labelClassName,
          )}
        >
          Usage Count
        </span>
        <div
          className={cn(
            "grow flex items-center gap-[10px] p-[16px] border border-black bg-white rounded-[10px]",
            counterClassName,
          )}
        >
          <button
            type="button"
            onClick={handleDecrement}
            aria-label="Decrease count"
            className={cn(
              "bg-[#F8F8F8] border-none flex-[0_0_40px] size-[40px] rounded-[5px] text-[24px] font-medium text-[rgba(0,0,0,0.80)] cursor-pointer flex items-center justify-center",
              buttonClassName,
            )}
          >
            -
          </button>
          <input
            type="number"
            value={count}
            onChange={(e) => {
              const val = parseInt(e.target.value);
              setCount(isNaN(val) ? 1 : Math.max(1, val));
            }}
            className="grow text-center text-[24px] font-medium bg-transparent border-none outline-none w-full"
          />
          <button
            type="button"
            onClick={handleIncrement}
            aria-label="Increase count"
            className={cn(
              "bg-[#F8F8F8] border-none flex-[0_0_40px] size-[40px] rounded-[5px] text-[24px] font-medium text-[rgba(0,0,0,0.80)] cursor-pointer flex items-center justify-center",
              buttonClassName,
            )}
          >
            +
          </button>
        </div>
        <button
          type="button"
          className={cn(
            "bg-[#E3E337] text-[14px] font-medium text-black border-none h-[70px] px-[70px] py-[12px] rounded-[20px] cursor-pointer",
            generateBtnClassName,
          )}
          onClick={() => handleGenerate(count)}
        >
          {generateLabel}
        </button>
      </div>
    );
  };

  return (
    <div
      className={cn(
        // Base layout and default "blue" style
        "box-border w-full max-w-[1080px] mx-auto",
        "flex flex-col gap-[30px] py-[40px]",
        className,
      )}
      style={style}
    >
      <div
        className={cn("flex flex-col items-center gap-[10px]", headerClassName)}
      >
        {icon}
        <h1
          className={cn(
            "text-[22px] md:text-[30px] font-bold text-black text-center",
            titleClassName,
          )}
        >
          {titleRender || "ZKP Temporary Password Generator"}
        </h1>
        <div
          className={cn(
            "w-0 border-t-[3px] border-dashed border-black inline-block ",
            lineClassName,
          )}
        ></div>
        <p
          className={cn(
            "text-center text-[14px] font-medium text-black",
            descriptionClassName,
          )}
        >
          Manage all your temporary passwords at{" "}
          <a
            href="https://web3.club"
            target="_blank"
            rel="noopener noreferrer"
            className={cn("text-[#FF8678] underline", linkClassName)}
          >
            web3.club
          </a>
        </p>
      </div>

      {renderContent()}
    </div>
  );
}
