import { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { CheckCircle, XCircle, Loader2 } from "lucide-react";
import { supabaseConfig } from "../../constants";

const SUPABASE_FUNCTIONS_URL = `${supabaseConfig.apiUrl}/functions/v1`;

interface PaymentStatus {
  sessionId: string;
  status: "pending" | "paid" | "transferred" | "failed";
  ethAmount: string;
  txHash: string | null;
  walletAddress: string;
}

export default function PaymentStatusPage() {
  const [searchParams] = useSearchParams();
  const sessionId = searchParams.get("session_id");
  const urlStatus = searchParams.get("status");

  const [payment, setPayment] = useState<PaymentStatus | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!sessionId) {
      setError("Missing session ID");
      setIsLoading(false);
      return;
    }

    const fetchStatus = async () => {
      try {
        const res = await fetch(
          `${SUPABASE_FUNCTIONS_URL}/get-payment-status?sessionId=${sessionId}`
        );
        const data = await res.json();

        if (!res.ok) {
          throw new Error(data.error);
        }

        setPayment(data);

        // 如果还在处理中，继续轮询
        if (data.status === "pending" || data.status === "paid") {
          setTimeout(fetchStatus, 3000);
        }
      } catch (err: any) {
        setError(err.message);
      } finally {
        setIsLoading(false);
      }
    };

    fetchStatus();
  }, [sessionId]);

  if (urlStatus === "cancelled") {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center p-8">
          <XCircle className="w-16 h-16 text-gray-400 mx-auto mb-4" />
          <h1 className="text-2xl font-bold mb-2">支付已取消</h1>
          <p className="text-gray-600 mb-4">您已取消本次支付</p>
          <a href="/" className="text-blue-600 hover:underline">
            返回首页
          </a>
        </div>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center p-8">
          <XCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
          <h1 className="text-2xl font-bold mb-2">出错了</h1>
          <p className="text-gray-600">{error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50">
      <div className="bg-white rounded-lg shadow-lg p-8 max-w-md w-full">
        {payment?.status === "transferred" ? (
          <SuccessView payment={payment} />
        ) : payment?.status === "failed" ? (
          <FailedView />
        ) : (
          <ProcessingView payment={payment} />
        )}
      </div>
    </div>
  );
}

function SuccessView({ payment }: { payment: PaymentStatus }) {
  return (
    <div className="text-center">
      <CheckCircle className="w-16 h-16 text-green-500 mx-auto mb-4" />
      <h1 className="text-2xl font-bold mb-2">支付成功</h1>
      <p className="text-gray-600 mb-4">
        {payment.ethAmount} ETH 已转入您的钱包
      </p>
      {payment.txHash && (
        <a
          href={`https://basescan.org/tx/${payment.txHash}`}
          target="_blank"
          rel="noopener noreferrer"
          className="text-blue-600 hover:underline text-sm"
        >
          查看交易详情
        </a>
      )}
      <div className="mt-6">
        <a
          href="/"
          className="inline-block bg-blue-600 text-white px-6 py-2 rounded-lg"
        >
          返回首页
        </a>
      </div>
    </div>
  );
}

function FailedView() {
  return (
    <div className="text-center">
      <XCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
      <h1 className="text-2xl font-bold mb-2">转账失败</h1>
      <p className="text-gray-600 mb-4">
        请联系客服处理
      </p>
    </div>
  );
}

function ProcessingView({ payment }: { payment: PaymentStatus | null }) {
  return (
    <div className="text-center">
      <Loader2 className="w-16 h-16 text-blue-600 mx-auto mb-4 animate-spin" />
      <h1 className="text-2xl font-bold mb-2">处理中</h1>
      <p className="text-gray-600">
        {payment?.status === "paid"
          ? "正在转账 ETH 到您的钱包..."
          : "正在确认支付..."}
      </p>
    </div>
  );
}
