import { createPublicClient, http, parseAbi } from "viem";
import { base } from "viem/chains";

const PROOF_OF_OWNERSHIP_ADDRESS: `0x${string}` =
  "0x7587CA385f1e10c411638003dA0f1bd3C99b919e";

const abi = parseAbi([
  "function getHashStatus(bytes32 _hash) view returns (bool isActive, address deployer, bool exists)",
]);

const publicClient = createPublicClient({
  chain: base,
  transport: http(
    "https://base-mainnet.infura.io/v3/d23ff549d2a64e9ebc0823d66997875c"
  ),
});

export interface ZkpPayload {
  a: [string, string];
  b: [[string, string], [string, string]];
  c: [string, string];
  input: [string];
}

export interface ZkpStatus {
  isActive: boolean;
  deployer: string;
  exists: boolean;
}

/**
 * Parse ZKP code string to ZkpPayload object
 */
export function parseZkp(input: string | ZkpPayload): ZkpPayload {
  if (typeof input === "string") {
    const s = input.trim();
    if (s.startsWith("{")) {
      return JSON.parse(s);
    }
    // Remove zero-width spaces and other invisible characters
    const cleanStr = s.replace(/[\u200B-\u200D\uFEFF]/g, "");
    const parts = cleanStr.split(/\s*,\s*/).map((p) => p.trim());
    if (parts.length !== 9) throw new Error("INVALID_ZKP_CODE");
    return {
      a: [parts[0], parts[1]],
      b: [
        [parts[2], parts[3]],
        [parts[4], parts[5]],
      ],
      c: [parts[6], parts[7]],
      input: [parts[8]],
    };
  }
  return input;
}

/**
 * Check if a ZKP hash is still valid (not revoked)
 */
export async function checkZkpStatus(zkpHash: string): Promise<ZkpStatus> {
  try {
    // Convert the decimal string to bytes32 hex
    const hashBigInt = BigInt(zkpHash);
    const hashHex = `0x${hashBigInt.toString(16).padStart(64, "0")}` as `0x${string}`;

    const result = await publicClient.readContract({
      address: PROOF_OF_OWNERSHIP_ADDRESS,
      abi,
      functionName: "getHashStatus",
      args: [hashHex],
    } as any);

    const [isActive, deployer, exists] = result as [boolean, string, boolean];

    return {
      isActive,
      deployer,
      exists,
    };
  } catch (error) {
    console.error("Error checking ZKP status:", error);
    throw error;
  }
}

/**
 * Verify if a ZKP code is still valid
 */
export async function isZkpValid(zkpCode: string | null | undefined): Promise<boolean> {
  if (!zkpCode) {
    return false;
  }

  try {
    const payload = parseZkp(zkpCode);
    const zkpHash = payload.input[0];
    const status = await checkZkpStatus(zkpHash);
    return status.exists && status.isActive;
  } catch (error) {
    console.error("Error validating ZKP:", error);
    return false;
  }
}

/**
 * Get ZKP storage key for a given address
 */
export function getZkpStorageKey(address: string | undefined): string {
  return `zkp_code_${address}`;
}

/**
 * Get stored ZKP code from localStorage
 */
export function getStoredZkpCode(address: string | undefined): string | null {
  if (!address) return null;
  return localStorage.getItem(getZkpStorageKey(address));
}

/**
 * Build URL with zkp parameter if zkpEnabled and valid zkp exists
 */
export function buildUrlWithZkp(
  url: string,
  zkpEnabled: boolean | undefined,
  address: string | undefined
): string {
  if (!zkpEnabled || !address) return url;

  const zkpCode = getStoredZkpCode(address);
  if (!zkpCode) return url;

  try {
    const encodedZkp = btoa(zkpCode);
    const urlObj = new URL(url);
    urlObj.searchParams.set("zkp", encodedZkp);
    return urlObj.toString();
  } catch {
    // If URL parsing fails, return original
    return url;
  }
}
